["NEWBIE_TOOLTIP_HONORABLE_KILLS"]="每当你或你的小队对一名最终死亡的 PvP 玩家造成伤害时，你都会获得荣誉击杀点数。你只能通过击杀绿色难度或更高（相当于会给你经验的怪物）的玩家来获得荣誉击杀点数。荣誉击杀只能通过击杀敌方玩家获得。",
["NEWBIE_TOOLTIP_HONOR_CONTRIBUTION_POINTS"]="在玩家对玩家（PvP）战斗中通过荣誉击杀获得荣誉。每次击杀获得的荣誉数量取决于你（或你的小队）对被杀玩家造成的伤害。你造成的伤害越多，获得的荣誉就越多。获得的荣誉将在小队或团队成员之间分配。此外，如果你在短时间内反复击败同一名玩家，获得的荣誉会减少。因此，在多次击杀同一名玩家后，你获得的荣誉会少得多，甚至不再获得荣誉。",
["NEWBIE_TOOLTIP_HONOR_STANDING"]="排名是你与同阵营（部落或联盟）所有其他玩家相比的分数。如果你的排名是 150，那么在你前面有 149 名玩家在同一时间段内获得了更多荣誉。要提升排名和军衔，你必须至少获得 25 次荣誉击杀。",
["NEWBIE_TOOLTIP_HORDE"]="一名骄傲的部落成员，是联盟成员（暗夜精灵、矮人、人类、侏儒和德莱尼）的敌人。",
["NEWBIE_TOOLTIP_IGNOREPLAYER"]="将一名玩家添加到你的屏蔽名单。你将无法看到屏蔽名单中玩家的任何消息或文字，他们也无法以任何方式与你交流。",
["NEWBIE_TOOLTIP_IGNORETAB"]="允许你修改被屏蔽玩家的名单。",
