["VOICEMACRO_20_Dw_1_FEMALE"]="我不喜欢待在地下。那让我想到死亡。",
["VOICEMACRO_20_Dw_2"]="哦，我的穿着好像有点问题。啊，我的锤子在那儿。",
["VOICEMACRO_20_Dw_2_FEMALE"]="我喜欢啤酒就像喜欢男人：颜色深、味道浓。",
["VOICEMACRO_20_Dw_3"]="我跟酒精没矛盾。我喝，我醉，我摔倒，就这样。",
["VOICEMACRO_20_Dw_3_FEMALE"]="就像我父亲常说的：\"闭嘴，滚出去\"。",
["VOICEMACRO_20_Dw_4"]="我每喝一口之间都会停下来。",
["VOICEMACRO_20_Dw_4_FEMALE"]="我叔叔有对黄铜做的球。真的！",
["VOICEMACRO_20_Dw_5"]="我喜欢啤酒就像喜欢女人；要有酒体，还要够苦。",
["VOICEMACRO_20_Dw_5_FEMALE"]="每天晚上我都用大锅修脚。我一个脚气都没有。我的脚干干净净。",
["VOICEMACRO_20_Dw_6"]="我可不是匿名戒酒会的人。所有人都认得我，我喝酒从不躲躲藏藏。",
["VOICEMACRO_20_Gn_0"]="知道吗？我很想有个花园，摆上几尊人类雕像。",
["VOICEMACRO_20_Gn_0_FEMALE"]="对我卷入的那场屠杀可能造成的任何不便，我深表歉意。",
["VOICEMACRO_20_Gn_1"]="我好像零钱不够。好吧，这个笑话真烂！",
["VOICEMACRO_20_Gn_1_FEMALE"]="我发现被痛打一顿还挺疼的。",
["VOICEMACRO_20_Gn_2"]="我希望能在这儿找到些有趣的玩意儿。我最爱摆弄小装置了。",
["VOICEMACRO_20_Gn_2_FEMALE"]="你知道的，被逼到绝路的松鼠也能要命。",
["VOICEMACRO_20_Gn_3"]="我设计了一个能把面包片放进去烤的装置，不过我想其实没人会用这种东西。",
["VOICEMACRO_20_Gn_3_FEMALE"]="但愿我有一天能找到下金蛋的母鸡。",
["VOICEMACRO_20_Gn_4"]="我想向诺莫瑞根的伙计们问好。大T、窥探者和小子迪斯……你们太棒了。个子小，但棒极了。",
["VOICEMACRO_20_Gn_5"]="我要是照放大镜，看起来就高大得多。",
["VOICEMACRO_20_Hu_0"]="掩护我。我溜到树后面去。",
["VOICEMACRO_20_Hu_0_FEMALE"]="为什么所有人都马上觉得我会缝纫和做饭？",
["VOICEMACRO_20_Hu_1"]="一个兽人肩上扛着鹦鹉走进酒吧。酒保说：\"嘿，你这东西从哪儿弄来的？\"鹦鹉回答：\"杜隆塔尔。那儿多的是\"。",
["VOICEMACRO_20_Hu_1_FEMALE"]="你有没有过无法掌控自己命运的感觉？就好像有只看不见的手在操纵你。",
["VOICEMACRO_20_Hu_2"]="一只鸭子走进药房说：\"请给我一张创可贴，我摔了一跤。\"药剂师回答：\"那可真是倒霉。\"",
["VOICEMACRO_20_Hu_2_FEMALE"]="有时候我控制不住自己说话的音量！",
["VOICEMACRO_20_Hu_3"]="牛头人怎么躲在樱花树上？把蹄子涂成红色。",
["VOICEMACRO_20_Hu_3_FEMALE"]="我喜欢在浴缸里放屁。",
["VOICEMACRO_20_Hu_4"]="有个人走过来对我说：\"我是帐篷，我是棚屋，我是帐篷，我是棚屋。\"我回答说：\"放松点，老兄，你太紧张了。\"",
["VOICEMACRO_20_Hu_4_FEMALE"]="我和朋友们互相换衣服穿。我们尺码都一样。",
["VOICEMACRO_20_Hu_5"]="\"我有个拍电影的好点子。讲的是两个侏儒找到了一个强大的护腕，必须把它送到燃烧平原，扔进大熔炉。他们组成了护腕同盟。一路上，一个叫高吞的鱼人痴迷于护腕，一路尾随他们。还有九个想抢走它的强盗。我们可以拍成三部曲，叫\"护腕之王\"。第一部可以叫\"护腕同盟\"，接着是\"两座塔\"，最后的高潮是\"嘿，王者归来\"。",
["VOICEMACRO_20_Hu_5_FEMALE"]="我急需修脚。",
["VOICEMACRO_20_Hu_6_FEMALE"]="我多想赶紧做完这个任务，好去找下一件加里波第物品。",
