["VOICEMACRO_20_Ni_0_FEMALE"]="知道吗？我晚上也不能停下来，不然我就会消失。",
["VOICEMACRO_20_Ni_1"]="知道吗？达纳苏斯那些远古守护者其实没那么老。",
["VOICEMACRO_20_Ni_1_FEMALE"]="说实话，我算是早起型的精灵。",
["VOICEMACRO_20_Ni_2"]="我正在翡翠梦境里，突然就想上厕所。",
["VOICEMACRO_20_Ni_2_FEMALE"]="知道吗？小精灵用来做个人清洁还挺好用的。",
["VOICEMACRO_20_Ni_3"]="那东西锋利吗？会割伤我吗？我现在可不是不朽的了，你知道吧？",
