["A Dungeon group has been found."]="已找到地下城队伍。",
["A GM would like to chat with you. Click here to begin."]="一名游戏管理员想与你交谈。点击此处开始。",
["A Mass Invite will populate your invite list based on a filter.|n|nNOTE: A Mass Invite clears your current invite list."]="批量邀请将根据筛选条件填充你的邀请列表。|n|n注意：批量邀请会清空你当前的邀请列表。",
["A buyer has been found for your auction of %s."]="你的 %s 拍卖已有买家。",
["A duck walked into an apothecary and he said, \"Give me some chapstick, and put it on my bill.\""]="一只鸭子走进药店说：\"给我点润唇膏，涂在我嘴上。\" 药剂师回答说：\"那你的嘴可真倒霉。\"",
["A group has been formed for:"]="已为以下目的组成队伍：",
["A group leader has removed your voice privileges."]="一名队长已取消你的语音权限。",
["A group leader has restored your voice privileges."]="一名队长已恢复你的语音权限。",
["A group leader may select this option to add the entire group to the battleground queue. Your group will enter the battleground at the same time."]="队长可以选择此选项，将整个队伍加入战场队列。你的队伍将同时进入战场。",
["A guy walked up to me and said, \"I'm a teepee, I'm a wigwam, I'm a teepee, I'm a wigwam.\"  I said, \"Relax, man, you're too tense.\""]="一个人走过来对我说：\"我是个帐篷，我是个棚屋，我是个帐篷，我是个棚屋。\"我说：\"放松点，老兄，你太紧张了。\"",
["A list of all the active quests you currently have. You can have up to 25 active quests at one time."]="列出你当前接下的所有任务。你同时最多可以拥有 25 个进行中的任务。",
["A macro script has been blocked from an action only available to the Blizzard UI."]="某个宏脚本尝试执行仅暴雪界面可用的操作，已被阻止。",
["A mail attachment was invalid."]="邮件附件无效。",
["A mail included too many attachments."]="一封邮件包含的附件过多。",
["A melee swing hit %4$s for %5$s.%6$s"]="一次近战攻击命中 %4$s，造成 %5$s 点伤害。%6$s",
["A more powerful spell is already active"]="已经有一个更强大的法术在生效",
["A player has left your Dungeon group. Would you like to find another player to finish %s?"]="一名玩家离开了你的地下城队伍。是否要寻找另一名玩家来完成 %s？",
["A proud member of the Alliance, opposed to members of the Horde (Orcs, Trolls, Tauren, Undead, Blood Elves)."]="一名骄傲的联盟成员，与部落成员（兽人、巨魔、牛头人、亡灵和血精灵）敌对。",
["A proud member of the Horde, opposed to members of the Alliance (Night Elves, Dwarves, Humans, Gnomes, Draenei)."]="一名骄傲的部落成员，与联盟成员（暗夜精灵、矮人、人类、侏儒和德莱尼）敌对。",
["A quest giver with a gray '!' over its head has a quest that you are too low level to accept. Check back once you gain a few levels."]="头顶有灰色 '!' 的任务给予者拥有一个你等级过低而无法接受的任务。等你提升几级后再来查看。",
["A quest related NPC or object is not functioning appropriately"]="任务相关 NPC 或物体功能异常",
["A raid difficulty change is currently in progress."]="团队副本难度正在切换中。",
["A ranged shot hit %4$s for %5$s.%6$s"]="一次远程攻击命中 %4$s，造成 %5$s 点伤害。%6$s",
["A role check has been initiated. Your group will be queued when all members have selected a role."]="已开始职责检查。当所有成员都选择职责后，你的队伍将加入队列。",
["A summon is already pending"]="已有一个待处理的召唤",
["A tool to help you find a group to join or find additional players to complete your newly created or existing group."]="帮助你寻找队伍，或为你的队伍寻找更多玩家的工具。",
["A trial account may only send whispers to characters that have you on their friends list."]="试玩账号只能向已将你加入好友列表的角色发送密语。",
["A vote has been initiated to remove %1$s from the group.\n\nThe reason given was:\n|cffffd200%2$s|r\n\nDo you want to kick %1$s?"]="已发起投票将 %1$s 移出队伍。\n\n给出的理由：\n|cffffd200%2$s|r\n\n是否要踢出 %1$s？",
