["Controls the number of ground clutter items, like grass and foliage.  Decrease to improve performance."]="控制草地或植被等地面杂物的数量。减少数量可提升性能。",
["Controls the number of particles used in effects caused by spells, fires, etc. Decrease to improve performance."]="控制用于法术、火焰等效果中的粒子数量。降低密度可提升性能。",
