["Each of the 21 gray bars below should be distinct from one another. Adjust the gamma slider until you can distinguish between each shade of gray. If using the slider alone is not enough to achieve this, adjust your monitor's brightness and contrast settings until satisfied."]="下面显示的 21 条灰色色条每一条都应能彼此区分。调整亮度校正滑块，直到你能分辨出每一级灰色。如果仅靠滑块无法达到这一效果，请适当调整显示器的亮度和对比度。",
["Each time you assist in killing a civilian in PvP that is too low of a level to give you experience (a gray level number), you will get a dishonorable kill.   Each dishonorable kill you get immediately reduces your overall ranking slightly, and each additional dishonorable kill you get during a single day has a larger effect than the last one.   Dishonorable kills are directly applied to your ranking."]="每次你参与击杀一名等级过低、不给你经验值（等级数字为灰色）的 PvP 平民时，你都会获得一次非荣誉击杀。每次非荣誉击杀都会立即略微降低你的总体军衔进度，而你在同一天内获得的每一次后续非荣誉击杀，其影响都会比上一次更大。此类击杀会直接作用于你的军衔。",
["Each time you or a group you are part of does damage to an enemy player in PvP that is subsequently killed you gain an honorable kill.   You only get an honorable kill if the target’s difficulty is green or better (the target would give you experience if it were a monster).    Only enemy players give honorable kills."]="每当你或你所在的队伍对一名 PvP 敌方玩家造成伤害，且该玩家随后死亡时，你都会获得一次荣誉击杀。只有当目标的难度为绿色或更高（即如果它是怪物会给你经验值）时，你才能获得荣誉击杀。只有敌方玩家才会提供荣誉击杀。",
