["Enables or disables game sound effects."]="启用或禁用游戏音效。",
["Enables reverb sound effects.  This will affect performance."]="启用混响音效。这会影响性能。",
["Enables software emulation for headphone surround sound."]="为耳机环绕声启用软件模拟。",
["Enables specular highlights on terrain. Disabling this can sometimes improve performance."]="启用地形的镜面高光。禁用此项有时可提升性能。",
