["Honor is gained by killing members of the opposite faction in PvP combat. You can use honor points to purchase special items."]="在 PvP 战斗中击杀敌对阵营成员可获得荣誉点数。你可以用这些点数购买特殊物品。",
["Honor is what you gain by making honorable kills in PvP combat.   How much honor you gain per kill is determined by how much damage you (or your group) did to the player that was killed, with more damage done equaling more honor.   This honor gain is split amongst the members of your group or raid group.   Also you will gain less honor for killing the same player over and over again in a short period of time, so after a few kills of the same player you will get little or no honor from killing them."]="荣誉是你在 PvP 战斗中取得荣誉击杀所获得的奖励。每次击杀获得的荣誉多少，取决于你（或你的队伍）对被击杀玩家造成的伤害，造成的伤害越多，获得的荣誉就越多。获得的荣誉会在你的小队或团队成员之间分配。此外，在短时间内反复击杀同一名玩家所获得的荣誉会减少，因此击杀同一名玩家几次之后，你从击杀他中获得的荣誉会很少，甚至没有。",
["Honor required it."]="荣誉要求如此。",
