["Horn Style"]="犄角样式",
["Hostile"]="敌对",
["Hot Issue"]="热点问题",
["How are you?"]="你好吗？",
["How does a Tauren hide in a cherry tree?  He paints his hooves red."]="牛头人怎么藏在樱花树里？他把蹄子涂成红色。",
["How generous."]="真是慷慨。",
["How kind of you."]="你真好心。",
["How much memory your AddOns are using. You can get to the addon management page from the character select screen."]="你的插件占用了多少内存。你可以从角色选择界面进入插件管理页面。",
["How you doing?"]="你过得怎么样？",
["How's it hanging?"]="最近怎么样？",
["Hunters require focus to use their abilities.  Focus generates while standing still."]="猎人需要集中值来使用技能。集中值在站立不动时产生。",
["Hurry, fire!"]="快，开火！",
["I always travel with %s."]="我总是带着 %s 一起旅行。",
["I am in your debt."]="我欠你个人情。",
["I apologize profusely for any inconvenience my murderous rampage may have caused."]="对于我这场杀戮狂欢可能造成的任何不便，我深表歉意。",
["I be feeling you."]="我懂你的意思。",
["I be in a bad way!"]="我很不好！",
["I be in a bad way."]="我很不好。",
["I be needing more mana!"]="我需要更多法力！",
["I believe so."]="我想是这样。",
["I can fulfill the role of:"]="我可以担任的角色：",
["I can't find anywhere to get my nails done."]="我到处都找不到地方做指甲。",
["I can't stand the smell of Orcs."]="我受不了兽人的气味。",
["I can't wait till this quest is done, and I can look for another Garibaldi artifact."]="我迫不及待想完成这个任务，好去找另一件加里波第神器。",
["I can't wait to suck the juice out of your eyeballs."]="我迫不及待想吸干你的眼球汁液。",
["I come from the Orcs.  We eat with spoons and forks.  We love to eat our pork."]="我来自兽人那边。我们用勺子和叉子吃饭，我们最爱吃猪肉。",
["I dig it."]="我喜欢。",
["I do hope to find some interesting gadgets around here.  I do love tinkering with things."]="我真希望能在这儿找到些有趣的小玩意。我确实喜欢摆弄各种东西。",
["I do not find you completely disagreeable."]="我并不觉得你完全令人讨厌。",
["I don't care that much about romance.  I fell in love before, and look what happened to me."]="我不太在意浪漫。我以前坠入过爱河，看看结果如何。",
["I don't drink anymore.  'Course, I don't drink any less, either."]="我不再喝酒了。当然，我喝的也没比以前少。",
["I don't feel that the 1 to 10 scale is fine enough to capture subtle details of compatibility.  I'd prefer a 12 dimensional compatibility scale with additional parameters for mechanical aptitude and torque."]="我觉得 1 到 10 分的量表不够精细，无法体现相容性的细微之处。我更希望有一套 12 维度的相容性量表，并加入机械适配度和扭矩等额外参数。",
["I don't have a drinking problem.  I drink, I get drunk, I fall down, no problem."]="我没有酗酒问题。我喝酒，我喝醉，我摔倒，没问题。",
["I don't know about you, but I can't understand a thing those Wisps say.  I usually just nod."]="我不知道你怎么想，但那些小精灵说的话我一个字也听不懂。我通常就点点头。",
["I don't like to be underground.  It reminds me of death."]="我不喜欢待在地下。那让我想起死亡。",
["I don't mind the Gnomes, but I'm always worried about tripping over one."]="我不讨厌侏儒，但我总担心会被他们绊倒。",
["I don't need to get funky.  I'm already there."]="说到玩转死亡，没人比我更在行。",
["I don't smell that bad for a dead dude, do I?"]="作为一个死人，我闻起来不算太糟，对吧？",
["I don't think so."]="我不这么认为。",
["I feel pretty, oh so pretty (spit)."]="我觉得自己很美，非常美（啐）。",
["I feel very feminine, and I'll beat the crap out of anyone who disagrees."]="我觉得自己很有女人味，谁敢不同意我就揍扁他。",
["I give myself a Dutch oven pedicure every night.  I've got no foot fungus at all.  My toes are pristine."]="我每晚都用大锅给自己做足部护理。我一点脚气都没有。我的脚趾完美无瑕。",
["I got a shrunken head.  I just came out of the pool."]="我的头缩水了。我刚从泳池里出来。",
["I got all this and personality, too."]="除了你看到的这些，我还很有个性。",
["I had an idea for a device that you could put small pieces of bread in to cook, but in the end I really didn't think there would be much of a market for it."]="我曾有个点子，做一种能放进小块面包烤熟的装置，但最后我觉得这东西根本不会有市场。",
["I have a number of inventions I'd like to show you back at my place."]="我家里有不少发明，想带你去看看。",
["I have no respect for people with small piercings.  I say go full hog.  Put a spear through your head."]="我瞧不起打小耳洞的人。我说要干就干大的，往脑袋正中间穿根长矛！",
["I heard a knee slapper once, and skipped my kneecap right across a lake."]="我听过一个特好笑的笑话，结果笑得膝盖骨都飞过了一个湖。",
["I heard if you cut off an extremity, it'll regenerate a little bigger.  Don't believe it."]="我听说如果你砍掉一截肢体，它会长得比原来大一点。我不信。",
["I hope you're not afraid of snakes."]="希望你不怕蛇。",
["I hope you're well rested.  You're going to need your strength."]="希望你休息好了。你会需要全部力气的。",
["I kill two dwarves in the morning, I kill two dwarves at night.  I kill two dwarves in the afternoon, and then I feel alright. I kill two dwarves in time of peace and two in time of war. I kill two dwarves before I kill two dwarves, and then I kill two more."]="我早上杀两个矮人，晚上再杀两个。我下午杀两个矮人，然后就感觉好多了。和平时杀两个矮人，战时也杀两个。我杀两个矮人之前先杀两个矮人，然后接着再杀两个。",
["I know.  My natural beauty is intimidating."]="我知道。我天生的美貌让人望而生畏。",
["I lead the way."]="我来带路。",
["I like large posteriors, and I cannot prevaricate."]="我喜欢大屁股，这我不能撒谎。",
["I like men who aren't afraid to cry; cry uncle."]="我喜欢不怕哭泣的男人；就是说，哭出来吧。",
["I like my ale like I like my men; dark and rich."]="我喜欢我的麦酒就像我喜欢男人：深色而浓郁。",
["I like my beer like I like my women; stout and bitter."]="我喜欢我的啤酒就像我喜欢女人：醇厚而苦涩。",
["I like my women dumpy and droopy with halitosis."]="我喜欢矮胖、松垮还带口臭的女人。",
["I like tall men."]="我喜欢高个子男人。",
["I like to fart in the tub."]="我喜欢在浴缸里放屁。",
["I look bigger in those mirrors where things look bigger."]="在那些会把人照大的镜子里，我看起来大多了。",
["I love you like a fat kid loves cake."]="我爱你就像胖小孩爱蛋糕。",
["I must be asleep, cause you're a dream come true.  Also, I'm slightly damp."]="我一定是在做梦，因为你是我梦想成真。另外，我还有点潮湿。",
["I need a hero."]="我需要一个英雄。",
["I need healing!"]="我需要治疗！",
["I need healing."]="我需要治疗。",
["I need help!"]="我需要帮助！",
["I need mana!"]="我需要法力！",
["I need more mana!"]="我需要更多法力！",
["I need some mana!"]="我需要一些法力！",
["I need to get my chest waxed again."]="我又得去给胸口脱毛了。",
["I once laughed so hard, I milked all over the floor."]="有一次我笑得太厉害，把奶挤得满地都是。",
["I owe you one."]="我欠你一个人情。",
["I require aid!"]="我需要援助！",
["I suppose so."]="我想是吧。",
["I thank you."]="我感谢你。",
["I think that guys just use the Emerald Dream as an excuse to avoid calling me back."]="我觉得男人们只是拿翡翠梦境当借口，好不给我回电话。",
["I think that last vendor short changed me.  Oh, that was a bad one."]="我觉得刚才那个商人少找我钱了。唉，这笑话真烂。",
["I want a man with soft hands.  Preferably four of them."]="我想要一个手温柔的男人。最好是四只手。",
["I will crush and destroy and... ooo... shiny..."]="我要碾碎、毁灭，还有……唔……亮晶晶……",
["I will lead the way."]="我来带路。",
["I will return the favor."]="我会报答你的。",
["I wish you well."]="祝你好运。",
["I won't bite you where it shows."]="我不会咬你看得见的地方。",
["I won't fall for any bad pickup line.  You've got to try two or three, at least."]="我不会被任何烂搭讪词打动。你至少得试上两三次。",
["I won't forget this."]="我不会忘记这件事。",
["I would expect the same."]="我期望的也是如此。",
["I would like to join a group"]="我想加入一个队伍",
["I'd like to give a shout out to my boys in Gnomeregan.  Keeping it real Big-T, Snoop-Pup, and Little Dees.  Y'all are short, but you're real, baby."]="我想向我在诺莫瑞根的兄弟们致敬。大 T、史努比狗和小迪斯……你们个子矮，但你们是真家伙。",
["I'd like to see you in a kilt."]="我想看你穿短裙。",
["I'd paint my toenails, but I'm not sure where they fell off."]="我本想涂脚趾甲，可我不确定它们掉哪儿去了。",
["I'll always treasure our time together."]="我会永远珍惜我们在一起的时光。",
["I'll give you crazy love."]="我会给你疯狂的爱。",
["I'll have you know I can flatten steel with my thighs."]="我要让你知道，我能用大腿把钢铁压平。",
["I'll lead the way."]="我来带路。",
["I'll miss you."]="我会想你的。",
["I'm a force of nature."]="我就是自然之力。",
["I'm also looking for a group for:"]="我也在寻找队伍，目标：",
["I'm dead, and I'm pissed."]="我死了，而且我很恼火。",
["I'm in a rotten mood."]="我今天心情糟透了。",
["I'm looking for a group for:"]="我正在寻找队伍，目标：",
["I'm out of mana!"]="我没法力了！",
["I'm short on mana!"]="我法力不多了！",
["I'm the type of girl my mother warned me about."]="我就是我妈当年警告我要远离的那种女孩。",
["I'm tired of the same old bull."]="我厌倦了这一套老掉牙的废话。",
["I've discovered that getting pummeled by a blunt weapon can be quite painful."]="我发现被钝器狠揍一顿还真挺疼的。",
["I've got big soulful eyes, long eyelashes, and a wet tongue.  What more could a guy want?"]="我有一双深情的大眼睛、长长的睫毛和湿漉漉的舌头。男人还能要求什么？",
["I've got no mana!"]="我没法力了！",
["IM Style"]="即时通讯风格",
["INTERNAL ERROR, DISMOUNTING A NON-PET"]="内部错误：正在解散的不是宠物",
["INTERNAL ERROR, YOU DON'T HAVE A PET TO DISMOUNT"]="内部错误：你没有可解散的宠物",
["Icon"]="图标",
["Icon Color"]="图标颜色",
["Icons in Chat"]="聊天中的图标",
["If I said you had a good body, would you hold it against me?"]="如果我说你身材不错，你会因此记恨我吗？",
["If I wasn't purple, you'd see I was blushing."]="要不是我一身紫色，你就能看见我脸红了。",
["If cannibalism be wrong, I don't want to be right."]="如果同类相食是错的，我不想当对的。",
["If checked, invitees whom respond to this event will have their status approved automatically; otherwise, you will have to approve them manually."]="若勾选此项，回应此活动的受邀者状态将自动设为已批准；否则你需要手动批准他们。",
["If checked, invitees will be unable to respond to this event."]="若勾选此项，受邀者将无法回应此活动。",
["If enabled, you will be able to look at your map to see the locations of certain quest objectives."]="若启用此项，你将能在地图上查看某些任务目标的位置。",
["If enabled, you will be able to review your talents in the Talent Interface before spending your talent points."]="若启用此项，你可以在花费天赋点之前先在天赋界面中查看你的天赋。",
["If enabled, you will only be able to receive loot by looting quest items, looting items that everyone passes on, or being given loot by the master looter."]="若启用此项，你只能通过拾取任务物品、拾取所有人放弃的物品，或由分配者分配来获得战利品。",
["If enabled, your character will automatically dismount before casting while flying."]="若启用此项，你的角色在飞行中施法前会自动解散坐骑。",
["If enabled, your character will automatically switch between auto attack and auto shot."]="若启用此项，你的角色将在自动攻击和自动射击之间自动切换。",
["If rot was hot, I'd be a volcano."]="如果腐朽是种时尚，我就是一座火山。",
["If the Name Plate is displayed for your current target, show the enemy cast bar with the target's health bar in the game field."]="若当前目标显示了姓名板，则在游戏画面中于目标生命值条旁显示敌人的施法条。",
["If the sole purpose or intent of any action is to continually upset, aggravate, or otherwise annoy another player, that action may be considered physical harassment or �grief play�.  Before reporting physical harassment, make sure that the situation that is being petitioned falls outside the realm of the PvP policy (www.worldofwarcraft.com/policy/pvp.shtml). "]="如果任何行为的唯一目的或意图是不断扰乱、激怒或以其他方式骚扰另一名玩家，该行为可能被视为人身骚扰或「恶意骚扰」。在举报人身骚扰之前，请确认所申诉的情况不属于 PvP 政策（www.worldofwarcraft.com/policy/pvp.shtml）的范畴。",
["If there is another player you have enjoyed playing with, add them to your friends list! Click on the |cffffd200Social Button|r and add them to your list of friends.|n|nYou can only add friends from your own realm."]="如果有其他玩家让你玩得开心，就把他加入好友列表！点击|cffffd200社交按钮|r并将其加入你的好友列表。|n|n你只能添加自己服务器上的好友。",
["If this is checked, sound will be recorded in the movie."]="若勾选此项，录制视频时将同时录制声音。",
["If this is checked, the game will offer the choice of compressing, ignoring, or deleting any pending movies when you log in."]="若勾选此项，登录时游戏会询问你是压缩、忽略还是删除待处理的视频。",
["If this is checked, the movie will be compressed when you stop recording. Otherwise, you will need to use the compress button to finish processing the movies."]="若勾选此项，停止录制时视频将被压缩。否则，你需要使用压缩按钮来完成视频处理。",
["If this is checked, you will see a movie camera icon appear on the minimap frame while recording. If the user interface is recorded, this will also appear in the movie."]="若勾选此项，录制期间你会在小地图框中看到一个摄影机图标。如果同时录制用户界面，该图标也会出现在视频中。",
["If this is checked, you will see the cursor in the movie. Regardless of this setting, you will see the cursor while playing."]="若勾选此项，你会在视频中看到光标。无论此设置如何，你在游戏时都会看到光标。",
["If this is checked, you will see the user interface in the movie. Regardless of this setting, you will see the user interface while playing."]="若勾选此项，你会在视频中看到用户界面。无论此设置如何，你在游戏时都会看到用户界面。",
["If you are the leader of a group, this button will add your current group to the battleground queue. Your group will be guaranteed to get into the same battleground instance at the same time.  Any group member added after you click this button or a group member in a queue for another battleground will not be guaranteed entrance to the same battleground."]="如果你是队伍的队长，此按钮会将你当前的队伍加入战场队列。你的队伍将保证同时进入同一战场副本。在你点击此按钮之后加入的队伍成员，或已在其他战场队列中的队伍成员，将无法保证进入同一战场。",
["If you belong to a party, you can right-click your portrait to bring up the Party Options menu. This menu will allow you to quit the party or see what looting rules the party is using. A party leader can add or remove party members, as well as change the party's looting rules."]="如果你属于一个小队，可以右键点击你的头像打开小队选项菜单。该菜单允许你退出小队或查看小队正在使用的拾取规则。队长可以添加或移除小队成员，也可以更改小队的拾取规则。",
["If you defeat an enemy and see sparkles on its corpse, that means it has loot.|n|n|cffffd200Right Click|r on a creature's corpse to loot it. This will open a loot window. Then |cffffd200Right Click|r on any items in that window to move them to your backpack."]="如果你击败了一个敌人并看到它的尸体在闪光，就说明它有战利品。|n|n|cffffd200右键点击|r生物的尸体即可拾取。这会打开战利品窗口。然后|cffffd200右键点击|r该窗口中的任意物品，即可将其放入你的背包。",
["If you find your corpse, you can resurrect for no penalty.  If I resurrect you all of your items will take up to 25%% durability damage (equipped and inventory) and you will be afflicted by %s of Resurrection Sickness."]="如果你找到自己的尸体，就可以无惩罚复活。如果我复活你，你的所有物品（已装备的和背包中的）将承受最多 25%% 的耐久度损失，并且你会受到 %s 的复活虚弱影响。",
["If you find your corpse, you can resurrect for no penalty.  If I resurrect you all of your items will take up to 25%% durability damage (equipped and inventory)."]="如果你找到自己的尸体，就可以无惩罚复活。如果我复活你，你的所有物品（已装备的和背包中的）将承受最多 25%% 的耐久度损失。",
["If you find your corpse, you can resurrect for no penalty.  Otherwise you will be afflicted by %s of Resurrection Sickness."]="如果你找到自己的尸体，就可以无惩罚复活。否则你会受到 %s 的复活虚弱影响。",
["If you find yourself stuck and unable to move, please try the auto-unstuck feature prior to petitioning a GM. In most cases, this should solve the problem. Activating the auto-unstuck command will first attempt to use your hearthstone to port you back to your inn. If this is not possible, it will attempt to nudge your character out of position.\n\nPlease note this option can only be used every 5 minutes. Using the auto-unstuck option will log your character and location so that we can verify and fix the location in the future."]="如果你发现自己被卡住、无法移动，请先试用自动卡死脱离功能，然后再联系 GM。在大多数情况下，这应该就能解决问题。启用自动卡死脱离命令后，会首先尝试用你的炉石将你传送回旅店。如果无法做到，它会尝试把你的角色从该位置推开。\n\n请注意此选项每 5 分钟只能使用一次。使用自动卡死脱离选项会记录你的角色和位置，以便我们日后核实并修复该位置。",
["If you replace this item, the following stat changes will occur:"]="如果你替换此物品，将发生以下属性变化：",
["If you stray into deep and uncharted waters, you will see a Fatigue bar. If you become completely fatigued, you will begin to drown."]="如果你误入深不可测的未知水域，就会看到一条疲劳条。当你完全疲劳时，就会开始溺水。",
