["It takes a long time after you try and use a spell or ability before the spell or ability actually occurs. Abilities may behave as if they are on cooldown even though they are not."]="在你尝试使用某个法术或技能之后，要过很久它才真正生效。技能可能会表现得像在冷却中一样，尽管实际并非如此。",
["It takes a long time for loot that you click on or that someone assigns to you to show up in your inventory. It may also take a long time to trade items with another player."]="你点击拾取或由他人分配给你的战利品，要过很久才出现在你的背包里。与其他玩家交易物品也可能需要很久。",
["It takes a long time for your friends to see messages you send them or for you to see messages they send you."]="你的好友要过很久才能看到你发给他们的消息，或者你要过很久才能看到他们发给你的消息。",
["It takes a long time to open mail or retrieve items from mail."]="打开邮件或从邮件中取回物品需要很久。",
