["Show messages when a spell or ability deals damage."]="当法术或技能造成伤害时显示消息。",
["Show messages when a spell or ability fails to deal damage. This includes dodges, parries, blocks, deflections, immunes, absorbs and evades."]="当法术或技能未能造成伤害时显示消息。包括目标免疫、躲闪、招架、格挡、偏斜、吸收和闪避的情况。",
["Show messages when a spell or ability fails to periodically deal damage. This includes immunes, absorbs and evades."]="当法术或技能未能造成周期性伤害时显示消息。包括目标免疫、吸收和闪避的情况。",
["Show messages when a spell or ability grants additional attacks, such as Windfury Weapon or Sword Specialization."]="当法术或技能给予额外攻击时显示消息，例如风怒武器或剑类武器专精。",
