["Show messages when a spell or ability interrupts another spell."]="当法术或技能打断另一个法术时显示消息。",
["Show messages when a spell or ability periodically deals damage, such as Shadow Word: Pain or Corruption."]="当法术或技能造成周期性伤害时显示消息，例如暗言术：痛或腐蚀术。",
["Show messages when a spell or ability periodically heals damage, such as Renew or Rejuvenation."]="当法术或技能周期性治疗伤害时显示消息，例如恢复或回春术。",
["Show messages when a spell or ability periodically performs any other effect, such as restoring or draining mana."]="当法术或技能周期性产生任何其他效果时显示消息，例如恢复或吸取法力。",
