["Show messages when a spell or ability restores mana, energy, rage, focus, or happiness."]="当法术或技能恢复法力、能量、怒气、集中值或快乐值时显示消息。",
["Show messages when a spell or ability resurrects another player or creature."]="当法术或技能复活另一名玩家或生物时显示消息。",
