["So long."]="再见。",
["So, I have this idea for a great movie.  It's about two Gnomes who find a bracelet of power, and they have to take it to the Burning Steppes and cast it into The Cauldron.  They form the Brotherhood of the Bracelet.  Along the way, they're trailed by a murloc named Gottom who's obsessed with the bracelet, and nine bracelet bogeymen.  It could be a three parter called \"Ruler of the Bracelet\".  The first part would be called \"The Brotherhood of the Bracelet\", followed by \"A Couple of Towers\", with the climactic ending called \"Hey, the King's Back\"."]="\"我有个拍大片的好点子。故事讲的是两个侏儒捡到了一只至尊魔戒，他们必须把它带到燃烧平原扔进大熔炉。他们组建了魔戒兄弟会。一路上，一个名叫戈托姆、对魔戒痴迷不已的鱼人追踪着他们，还有九个魔戒恶鬼。可以拍成三部曲，名叫\"魔戒之王\"。第一部叫\"魔戒兄弟会\"，接着是\"两座塔\"，最后的高潮部分叫\"嘿，国王回来了\"。",
["So, an Orc walks into a bar with a parrot on his shoulder.  The bartender says, \"Hey, where'd you get that?\"  The parrot says, \"Durotar.  They got 'em all over the place.\""]="一个兽人肩上扛着鹦鹉走进酒吧。酒保说：\"嘿，你从哪儿弄来的？\"鹦鹉说：\"杜隆塔尔，那儿到处都是。\"",
["So, you want to fight for the glory of victory in the games? Well, you're going to have to wait. The Steamwheedle Cartel is taking a break after the great excitement of last season! Come back next week for your shot at glory! Feel free to practice in the meantime, but the true fun will have to wait."]="这么说，你想在比赛中为胜利的荣耀而战？那你可得等等了。热砂集团在上赛季的狂热之后正在休整！下周再来争取你的荣耀吧！期间你可以随意练习，但真正的乐趣还得再等等。",
