["The amount of experience (XP) you have earned. The color of the XP bar indicates your rest state: light blue for Rested, and purple for Normal. Rested players earn twice the experience they would normally gain from slaying a monster. Characters become less rested when they kill monsters, and more rested by spending time at or logging out at an inn or city."]="你已获得的经验值（XP）。经验条的底色表示你的休息状态：浅蓝色为已休息，紫色为普通。已休息的玩家击杀怪物获得的经验值是平时的两倍。角色击杀怪物会减少休息状态，在旅店或城市中停留或下线则会增加休息状态。",
["The amount of happiness your pet currently has. Content pets inflict normal damage on their enemies, whereas Happy pets inflict enhanced damage, and unhappy pets inflict reduced damage. Happiness goes down when your pet dies or as it grows hungry, while feeding your pet will increase its happiness."]="你的宠物当前的快乐值。满足的宠物对敌人造成正常伤害，快乐的宠物造成额外伤害，不快乐的宠物造成的伤害降低。宠物死亡或饥饿时快乐值会下降，喂食宠物则会提升快乐值。",
["The amount of health you currently have. If your health reaches zero, you will die. Health automatically regenerates when you are out of combat."]="你当前拥有的生命值。生命值降为零你就会死亡。脱离战斗后生命值会自动恢复。",
