["These Settings"]="这些设置",
["These are general gameplay related controls that affect how your character interacts with objects and other players in the game world."]="这些是与游戏玩法相关的通用控制选项，影响你的角色与游戏世界中的物体和其他玩家互动的方式。",
["These are the factions that you have interacted with."]="这些是你接触过的阵营。",
["These are the lowest recommended graphics settings for the game. These settings provide excellent performance."]="这是游戏推荐的最低画质设置。这些设置可提供出色的性能。",
["These are your active talents"]="这些是你已激活的天赋",
["These controls allow you to modify specific detail levels for many game elements and effects."]="这些控制选项允许你调整许多游戏元素和效果的具体细节等级。",
["These items can't be swapped."]="这些物品无法更换。",
["These options affect whether certain UI and character elements are hidden or displayed."]="这些选项决定某些界面和角色元素是隐藏还是显示。",
["These options affect your character's behaviors in combat, and allow you to change the way combat is displayed in the UI."]="这些选项影响你角色在战斗中的行为，并允许你更改界面中战斗信息的显示方式。",
["These options allow you to change details having to do with stereoscopic (3D) viewing."]="这些选项允许你更改与立体（3D）显示相关的细节。",
["These options allow you to change the behavior of the help systems within the game."]="这些选项允许你更改游戏内帮助系统的行为。",
["These options allow you to change the size and detail in which your video hardware renders the game."]="这些选项允许你更改显卡渲染游戏时的尺寸和细节。",
["These options allow you to change the types of Battle.net messages you receive."]="这些选项允许你更改你接收的 Battle.net 消息类型。",
["These options allow you to change the way the mouse behaves inside the game."]="这些选项允许你更改鼠标在游戏内的行为。",
["These options allow you to configure the floating combat text which can be displayed in the center of the screen, making it easier to follow battles."]="这些选项允许你配置可显示在屏幕中央的浮动战斗文本，让你更容易跟上战斗进程。",
["These options allow you to control and modify your interactions with other players you encounter in Azeroth."]="这些选项允许你控制和修改与你在艾泽拉斯遇到的其他玩家的互动方式。",
["These options allow you to control how buffs and debuffs are displayed."]="这些选项允许你控制增益和减益的显示方式。",
["These options allow you to control which names are visible within the game field while you play."]="这些选项允许你控制游戏画面中哪些名字可见。",
["These options allow you to customize how game objectives like Quests and Achievements are displayed in the user interface,"]="这些选项允许你自定义任务和成就等游戏目标在用户界面中的显示方式。",
["These options allow you to customize the behaviors of the game's quest interface."]="这些选项允许你自定义游戏任务界面的行为。",
["These options allow you to display detailed information on status bars throughout the game."]="这些选项允许你在整个游戏中显示状态条上的详细信息。",
["These options allow you to enable and disable full game features."]="这些选项允许你启用或禁用游戏的整体功能。",
["These options allow you to modify language settings for the game."]="这些选项允许你修改游戏的语言设置。",
["These options allow you to modify the camera's behavior inside the game."]="这些选项允许你修改游戏内镜头的表现。",
["These options can be used to change the display and behavior of party and raid frames within the UI."]="这些选项可用于更改界面中小队和团队框体的显示与行为。",
["These options can be used to change the display and behavior of unit frames within the UI."]="这些选项可用于更改界面中单位框体的显示与行为。",
["These options control sound hardware and input settings for the voice chat system."]="这些选项控制语音聊天系统的声卡和输入设置。",
["These options control sound hardware and the types and volumes of sounds within the game."]="这些选项控制声卡以及游戏内声音的类型和音量。",
["These options control the ranges and levels of detail used to draw effects and objects in the game."]="这些选项控制游戏中绘制效果和物体时使用的距离和细节等级。",
["These settings provide the very best quality and should only be used on high-end systems."]="这些设置可提供最佳画质，仅建议在高配置系统上使用。",
["They will speak of your exploits for generations."]="世世代代都会传颂你的丰功伟绩。",
["This Dungeon is In Progress."]="该地下城正在进行中。",
["This Item Begins a Quest"]="该物品可开启一个任务",
["This Season"]="本赛季",
["This Week"]="本周",
["This achievement has already been completed."]="该成就已经完成。",
["This allows you to save sets of equipment. You will then be able to equip a set by clicking on the icon. Once enabled, the Equipment Manager can be accessed through the character frame."]="此功能允许你保存装备方案。之后你只需点击图标即可装备某个方案。启用后，可以通过角色框体访问装备管理器。",
["This codec is faster to compress than H.264 but it will generate a bigger file. "]="此编解码器压缩速度比 H.264 更快，但生成的文件更大。",
["This codec is supported natively by Apple devices like the iPod, iPhone and AppleTV. This codec has the best ratio quality/size but it is also the slowest to compress."]="Apple 设备（如 iPod、iPhone 和 AppleTV）原生支持此编解码器。此编解码器的画质／体积比最佳，但压缩速度也最慢。",
["This determines how you will interact with members of this faction. If you have at war checked then your default behavior will be to attack them. If you do not have it checked you will not be able to attack them. "]="这决定你与该阵营成员的互动方式。如果勾选了交战，你的默认行为将是攻击他们；如果没有勾选，你将无法攻击他们。",
["This doesn't mean I like you."]="这不代表我喜欢你。",
["This event has already occured."]="此活动已经举办过了。",
["This event is locked."]="此活动已被锁定。",
["This feature becomes available at level %d."]="该功能在 %d 级解锁。",
["This guild bank tab is full"]="该公会银行标签页已满",
["This includes information about:  an upcoming patch (what, when, how), upcoming content additions, game play changes, and future rule changes."]="其中包括以下信息：即将到来的补丁（内容、时间、方式）、即将推出的内容更新、游戏玩法改动以及未来的规则变更。",
["This includes information about:  quests, non-player characters (NPCs), items, locations, or anything else that the player could possibly find out through exploration and/or interaction with the world or other players."]="其中包括以下信息：任务、非玩家角色（NPC）、物品、地点，或玩家通过探索及／或与世界或其他玩家互动可能获知的任何其他内容。",
["This is a character you have enjoyed playing with on your realm, You can party and chat with this character."]="这是你在服务器上一起玩得很开心的角色。你可以与此角色组队和聊天。",
["This is a flight master who trains flying beasts to carry passengers from one location to another. For a minimal fee, you can swiftly travel to other flight masters that you have spoken to in the past.|n|nWhen you discover a new city, finding the flight master will allow you to return easily in the future."]="这是一位飞行管理员，他们驯养飞行生物来运送乘客往返各地。只需支付少量费用，你就可以迅速飞往你曾经交谈过的其他飞行管理员处。|n|n当你发现一座新城市时，找到飞行管理员就能让你以后轻松返回。",
["This is a person you know and trust in real life. You will be able to chat with them no matter which Blizzard game you are playing. They must accept your friend invite, at which point your real name will be displayed to all of their friends."]="这是你在现实生活中认识和信任的人。无论你在玩哪款暴雪游戏，都可以与他们聊天。对方必须接受你的好友邀请，之后你的真实姓名将显示给他们所有的好友。",
["This is a trial version of World of Warcraft. Some features are not available. To experience all of the game go to www.worldofwarcraft.com."]="这是《魔兽世界》的试玩版本。部分功能不可用。如需体验完整游戏，请访问 www.worldofwarcraft.com。",
["This is how long you can record a movie before you run out of disk space. The game will stop recording after that time."]="这表示在磁盘空间用尽前你可以录制多长的影片。超过该时间后游戏将停止录制。",
["This is how much data needs to be written to your hard drive every second. If the game becomes very choppy while recording then it might be that the data rate is too high for your hard drive. The game will stop recording if it cannot write the data fast enough."]="这表示每秒需要向硬盘写入的数据量。如果录制时游戏变得非常卡顿，可能是数据速率对硬盘来说过高了。如果无法足够快地写入数据，游戏将停止录制。",
