["To create a guild you must purchase this charter, get 9 unique player signatures, and return the charter to me.  Please enter the desired name for your guild."]="要创建公会，你必须购买这份章程，获得 9 名不同玩家的签名，然后把章程交还给我。请输入你想要的公会名称。",
["To create an arena team you must purchase this charter, get the same number of unique player signatures as the size of your team, and return the charter to me.  Please enter the desired name for your arena team."]="要创建竞技场队伍，你必须购买这份章程，获得与队伍规模相同数量的不同玩家签名，然后把章程交还给我。请输入你想要的竞技场队伍名称。",
["To fight enemies, first use |cffffd200Left Click|r to target them. Then click on one of the abilities on the action bar across the bottom of your screen.|n|nYou should use ranged abilities while the target is still far away. Other abilities require you to be close to your target, particularly if your class specializes in melee weapons."]="要与敌人战斗，首先用|cffffd200鼠标左键|r选中他们。然后点击屏幕底部动作条上的某个技能。|n|n当目标距离还很远时，你应该使用远程技能。其他技能则需要你靠近目标，尤其是当你的职业专精于近战武器时。",
["To free up bag space or make some money you can sell some of the items you have collected.|n|nLocate a vendor and |cffffd200Right Click|r them. Then open your bags and |cffffd200Right Click|r on any items you want to sell."]="想要腾出背包空间或赚点钱，你可以出售一些收集到的物品。|n|n找到一名商人并|cffffd200点击右键|r与其交谈。然后打开背包，对你想出售的物品|cffffd200点击右键|r。",
["To get started, you should begin a |cffffd200Quest|r.|n|nThere's a quest giver right in front of you. Tutorial tips will help you along the way.|n|nThank you for playing, and good luck in your adventures!"]="作为开始，你应该先接一个|cffffd200任务|r。|n|n你面前就有一位任务给予者。教学提示会一路帮助你。|n|n感谢你的游玩，祝你的冒险之旅好运！",
["To my side!"]="到我身边来！",
