["You can drink to regain your mana faster. |cffffd200Right Click|r on a beverage to drink it.|n|nYou don't need to drink if your class does not use mana."]="你可以通过饮用来更快恢复法力。对饮料|cffffd200点击右键|r即可饮用。|n|n如果你的职业不使用法力，就不需要饮用。",
["You can eat food to gain health faster. |cffffd200Right Click|r on food to eat it."]="你可以通过进食来更快恢复生命值。对食物|cffffd200点击右键|r即可食用。",
