["You have obtained a ranged weapon. To use it, first equip the weapon by opening your |cffffd200Character Info|r and your |cffffd200Backpack|r and dragging the item onto your character.|n|nThen, open up your |cffffd200Spellbook|r and drag the |cffffd200Shoot|r or |cffffd200Throw|r ability onto your action bar.|n|nOnly hunters, warriors and rogues may use ranged weapons. Mages, priests and warlocks may use wands."]="你获得了一件远程武器。要使用它，请先装备这件武器：打开|cffffd200角色信息|r和|cffffd200背包|r，把该物品拖到你的角色身上。|n|n然后打开你的|cffffd200法术书|r，把|cffffd200射击|r或|cffffd200投掷|r技能拖到动作条上。|n|n只有猎人、战士和潜行者可以使用远程武器。法师、牧师和术士可以使用魔杖。",
