["You know I have to keep moving at night or I'll disappear."]="你知道的，晚上我必须一直走动，不然我就会消失。",
["You know how hard it is to get your groove on with the spirit of your great grandmother looking over you?"]="你知道在你曾祖母的灵魂注视下想放松有多难吗？",
