["You know, I really wish I had a garden where I could put a couple of human statues."]="你知道的，我真希望能有个花园，好摆上几尊人类雕像。",
["You know, Taurens are born hunters.  You ever see a Tauren catch a salmon out of a stream?  It really is quite exciting.  And, have you ever seen a Tauren stalk a python?  'Course you haven't.  That's because Taurens are so adept at blending in with their surroundings."]="你知道的，牛头人生来就是猎人。你见过牛头人从溪流里抓起一条鲑鱼吗？那可真叫人大开眼界。还有，你见过牛头人潜行跟踪一条巨蟒吗？你当然没见过。那是因为牛头人太擅长融入周围环境了。",
["You know, Wisps are actually pretty useful for personal hygiene."]="你知道的，小精灵其实对个人卫生挺有用的。",
["You know, older bulls really only have one function."]="你知道的，老公牛其实只有一个用处。",
